<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Bouncing Ball Playground</title>
<style>
  html, body {
    margin: 0;
    padding: 0;
    background: #14161c;
    color: #e8eaf0;
    font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
    min-height: 100vh;
  }
  .wrap {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    gap: 18px;
    padding: 24px 0;
    box-sizing: border-box;
  }
  h1 {
    font-size: 20px;
    font-weight: 600;
    letter-spacing: 0.5px;
    margin: 0;
    color: #aeb6c8;
  }
  #sim {
    width: 480px;
    height: 480px;
    max-width: 90vw;
    background: radial-gradient(circle at 30% 25%, #1e2230, #101218);
    border: 1px solid #2a2f3c;
    border-radius: 12px;
    box-shadow: 0 10px 40px rgba(0,0,0,0.5);
    cursor: crosshair;
    display: block;
  }
  .controls {
    display: flex;
    gap: 12px;
  }
  button {
    background: #232838;
    color: #e8eaf0;
    border: 1px solid #363c4f;
    padding: 10px 20px;
    font-size: 14px;
    border-radius: 8px;
    cursor: pointer;
    transition: background 0.15s, transform 0.08s;
  }
  button:hover { background: #2e3550; }
  button:active { transform: translateY(1px); }
  .hint { font-size: 12px; color: #6b7386; }
</style>
</head>
<body>
<div class="wrap">
  <h1>Bouncing Ball Playground</h1>
  <canvas id="sim" width="480" height="480"></canvas>
  <div class="controls">
    <button id="drop">Drop</button>
    <button id="play">Pause</button>
    <button id="clear">Clear</button>
  </div>
  <div class="hint">Click the canvas to add a ball</div>
</div>
<script>
(function () {
  const canvas = document.getElementById('sim');
  const ctx = canvas.getContext('2d');
  const W = canvas.width;
  const H = canvas.height;

  const GRAVITY = 0.35;      // per step at dt=1
  const RESTITUTION = 0.8;   // energy loss on bounce
  const DEFAULT_R = 14;

  let balls = [];
  let playing = true;

  const COLORS = ['#ff6b6b', '#ffd93d', '#6bcB77', '#4d96ff', '#c77dff', '#ff9f45', '#43e6c7'];
  let colorIdx = 0;

  function makeColor() {
    const c = COLORS[colorIdx % COLORS.length];
    colorIdx++;
    return c;
  }

  function addBall(x, y, vx = 0, vy = 0, r) {
    if (r === undefined || r === null) r = DEFAULT_R;
    r = Math.max(2, Math.min(r, Math.min(W, H) / 2 - 1));
    // clamp initial position inside bounds
    x = Math.max(r, Math.min(W - r, x));
    y = Math.max(r, Math.min(H - r, y));
    const b = { x, y, vx, vy, r, color: makeColor() };
    balls.push(b);
    draw();
    return b;
  }

  function clear() {
    balls = [];
    draw();
  }

  function step(dt = 1) {
    for (const b of balls) {
      // gravity
      b.vy += GRAVITY * dt;

      // integrate
      b.x += b.vx * dt;
      b.y += b.vy * dt;

      // left / right walls
      if (b.x - b.r < 0) {
        b.x = b.r;
        b.vx = -b.vx * RESTITUTION;
      } else if (b.x + b.r > W) {
        b.x = W - b.r;
        b.vx = -b.vx * RESTITUTION;
      }

      // top / bottom (floor & ceiling)
      if (b.y - b.r < 0) {
        b.y = b.r;
        b.vy = -b.vy * RESTITUTION;
      } else if (b.y + b.r > H) {
        b.y = H - b.r;
        b.vy = -b.vy * RESTITUTION;
      }
    }
    draw();
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);
    for (const b of balls) {
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
      const grad = ctx.createRadialGradient(
        b.x - b.r * 0.35, b.y - b.r * 0.35, b.r * 0.1,
        b.x, b.y, b.r
      );
      grad.addColorStop(0, '#ffffff');
      grad.addColorStop(0.25, b.color);
      grad.addColorStop(1, b.color);
      ctx.fillStyle = grad;
      ctx.fill();
      ctx.lineWidth = 1;
      ctx.strokeStyle = 'rgba(0,0,0,0.25)';
      ctx.stroke();
    }
  }

  // animation loop
  function loop() {
    if (playing) step(1);
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);

  // canvas click -> add ball at cursor
  canvas.addEventListener('click', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = (e.clientX - rect.left) * (W / rect.width);
    const y = (e.clientY - rect.top) * (H / rect.height);
    const vx = (Math.random() - 0.5) * 6;
    addBall(x, y, vx, 0, 10 + Math.random() * 12);
  });

  // buttons
  document.getElementById('drop').addEventListener('click', () => {
    const x = W * (0.25 + Math.random() * 0.5);
    addBall(x, 30, (Math.random() - 0.5) * 4, 0, 10 + Math.random() * 12);
  });

  const playBtn = document.getElementById('play');
  playBtn.addEventListener('click', () => {
    playing = !playing;
    playBtn.textContent = playing ? 'Pause' : 'Play';
  });

  document.getElementById('clear').addEventListener('click', clear);

  // Expose API
  window.sim = {
    get w() { return W; },
    get h() { return H; },
    balls() {
      return balls.map(b => ({ x: b.x, y: b.y, vx: b.vx, vy: b.vy, r: b.r }));
    },
    addBall(x, y, vx = 0, vy = 0, r) { return addBall(x, y, vx, vy, r); },
    clear() { clear(); },
    step(dt = 1) { step(dt); },
  };

  // initial draw
  draw();
})();
</script>
</body>
</html>
